const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Karachi'}).format(new Date());
async function api(path:string,method='GET',body?:unknown){const epoch=sessionEpoch;const res=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(epoch!==sessionEpoch)throw Error('Session changed. Please retry in the current session.');if(data.session_minutes)sessionLifetime=data.session_minutes*60000;if(!res.ok){if(res.status===401)window.dispatchEvent(new Event('session-expired'));throw Error(data.error||'Request failed.')}return data}
function Badge({children,tone=''}:{children:React.ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
