const recovery=useOnlineDraft({api,user,state:{cart:{idempotency_key:key,lines:cart.map(l=>({medicine_id:l.medicine.id,unit_id:l.unit.id,quantity:l.quantity})),discount_paisa:Math.round(Number(discount)*100),customer_id:customer||null,notes,prescription_ref:prescriptionRef||undefined},label:cartLabel,saved_cart_id:savedId||null},onClear:()=>{setCart([]);setKey(crypto.randomUUID());setDiscount('0');setCustomer('');setNotes('');setPrescriptionRef('');setCartLabel('');setSavedId('');setApproval('');setQuote(null)},onRestore:result=>{const state=result.draft.state;setCart(result.lines);setKey(state.cart.idempotency_key);setDiscount(String(state.cart.discount_paisa/100));setCustomer(state.cart.customer_id||'');setNotes(state.cart.notes||'');setPrescriptionRef(state.cart.prescription_ref||'');setCartLabel(state.label);setSavedId(state.saved_cart_id||'');setApproval('');setQuote(null);setSuccess('Online cart recovered at current prices. Review stock and payment again.')}});
