useEffect(()=>{if(!user)return;let lastAction=Date.now(),lastSent=Date.now(),locked=false;const lock=()=>{if(locked)return;locked=true;void api('/auth/logout','POST',{preserve_cookie:true}).catch(()=>{});window.dispatchEvent(new Event('session-expired'))};const active=()=>{if(locked)return;if(Date.now()-lastAction>=sessionLifetime){lock();return}lastAction=Date.now()};for(const event of ['pointerdown','keydown','touchstart'])window.addEventListener(event,active);const timer=setInterval(()=>{if(locked)return;if(Date.now()-lastAction>=sessionLifetime){lock();return}if(lastAction>lastSent&&Date.now()-lastSent>=60000){lastSent=Date.now();void api('/auth/activity','POST').catch(()=>{})}},15000);return()=>{locked=true;clearInterval(timer);for(const event of ['pointerdown','keydown','touchstart'])window.removeEventListener(event,active)}},[user]);
