function rememberDialogTarget(){if(!modal&&document.activeElement instanceof HTMLElement)dialogReturn.current=document.activeElement}
async function load(){if(!user||page==='offline')return;if(page==='medicines')setCategories(await api('/categories'));const p=await api('/profile');setProfile(p);if(['pos','medicines','purchases'].includes(page)){const d=await api('/medicines?query='+encodeURIComponent(page==='purchases'?'':query)+'&offset='+(page==='purchases'?0:catalogOffset)+'&status='+(page==='medicines'?catalogStatus:'active')+'&category='+(page==='medicines'?catalogCategory:''));setItems(d.items)}if(page==='dashboard'||page==='reports'){if(can('reports'))setData(await api('/reports/daily?date='+reportDate));else setData({restricted:true})}if(page==='inventory')setData(await api('/batches'));if(page==='pos')setSavedCarts(await api('/carts'));if(page==='sales')setData(await api('/sales?query='+encodeURIComponent(query)+'&from='+salesFrom+'&to='+salesTo+'&offset='+salesOffset));if(page==='purchases'){setData(await api('/purchases'));setSuppliers(await api('/suppliers'))}if(page==='settings'&&user.is_super_admin)setUsers(await api('/users'))}
