useEffect(()=>{const handler=(event:KeyboardEvent)=>{const action=cashierShortcut(event,{page,modal,busy:busy||posting.current,blocked:recovery.blocked,canSell:can('sales'),cartSize:cart.length,hasReceipt:!!sale});if(!action)return;event.preventDefault();switch(action){case 'search':focusControl(searchRef.current);break;case 'quantity':focusControl(document.querySelector<HTMLElement>('[data-cart-qty]'));break;case 'customer':focusControl(document.querySelector<HTMLElement>('#pos-customer'));break;case 'discount':focusControl(document.querySelector<HTMLElement>('#pos-discount'));break;case 'payment':void reviewPayment();break;case 'print':void printReceipt();break}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)},[cart,page,modal,discount,key,busy,recovery.blocked,user,sale,customer,notes,prescriptionRef,approval]);
async function holdCart(){await run(async()=>{await recovery.verifyCheckout();const id=key;const {idempotency_key,payments,...cartData}=payload();await api('/carts','POST',{id,label:cartLabel||'Saved sale',cart:cartData});await recovery.clear().catch(()=>{});mutateCart([]);setDiscount('0');setCustomer('');setNotes('');setPrescriptionRef('');setCartLabel('');setSavedId('');await load();setSuccess('Cart saved. Stock and prices are checked again on checkout.')})}
